import json
import sys
import struct
import zlib

MAX_PAYLOAD = 4096
KIND_BEGIN = 1
KIND_PATCH = 2
KIND_COMMIT = 3
KIND_ABORT = 4


def solve(request):
    pages = [bytearray.fromhex(p) for p in request["pages"]]
    checkpoint = request["checkpoint"]
    log_hex = request["log"]
    if len(log_hex) % 2:
        log_hex = log_hex[:-1]
    data = bytes.fromhex(log_hex)

    n = len(data)
    pos = 0
    last_seq = 0
    valid_bytes = 0

    # transaction_id -> (list_of_patch_payloads, list_of_(page_index, byte_offset, data))
    active = {}

    while pos + 13 <= n:
        payload_length = struct.unpack_from("<I", data, pos)[0]
        sequence = struct.unpack_from("<I", data, pos + 4)[0]
        kind = data[pos + 8]
        transaction_id = struct.unpack_from("<I", data, pos + 9)[0]

        # header validation
        if payload_length > MAX_PAYLOAD:
            break
        if sequence <= last_seq:
            break
        if transaction_id == 0:
            break
        if kind < 1 or kind > 4:
            break

        end = pos + 13 + payload_length + 4
        if end > n:
            break

        payload = data[pos + 13:pos + 13 + payload_length]
        crc_stored = struct.unpack_from("<I", data, pos + 13 + payload_length)[0]
        crc_calc = zlib.crc32(data[pos:pos + 13] + payload) & 0xFFFFFFFF
        if crc_stored != crc_calc:
            break

        # payload shape validation
        patch = None
        if kind == KIND_BEGIN or kind == KIND_ABORT:
            if payload_length != 0:
                break
        elif kind == KIND_PATCH:
            if payload_length < 6:
                break
            page_index, byte_offset, byte_count = struct.unpack_from("<HHH", payload, 0)
            if byte_count == 0:
                break
            if payload_length != 6 + byte_count:
                break
            if page_index >= len(pages):
                break
            if byte_offset + byte_count > len(pages[page_index]):
                break
            patch = (page_index, byte_offset, payload[6:6 + byte_count])
        else:  # KIND_COMMIT
            if payload_length != 8:
                break

        # structurally valid -> semantic effect
        if kind == KIND_BEGIN:
            active[transaction_id] = ([], [])
        elif kind == KIND_PATCH:
            inc = active.get(transaction_id)
            if inc is not None:
                inc[0].append(payload)
                inc[1].append(patch)
        elif kind == KIND_ABORT:
            active.pop(transaction_id, None)
        else:  # COMMIT
            inc = active.pop(transaction_id, None)
            if inc is not None:
                patch_count, digest = struct.unpack_from("<II", payload, 0)
                calc = zlib.crc32(b"".join(inc[0])) & 0xFFFFFFFF
                if patch_count == len(inc[1]) and digest == calc and sequence > checkpoint:
                    for page_index, byte_offset, pdata in inc[1]:
                        pages[page_index][byte_offset:byte_offset + len(pdata)] = pdata

        last_seq = sequence
        pos = end
        valid_bytes = pos

    return {
        "pages": [bytes(p).hex() for p in pages],
        "valid_bytes": valid_bytes,
        "last_seq": last_seq,
    }


if __name__ == "__main__":
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        print(json.dumps(solve(json.loads(line))))
